/**
 * Restores a workspace within its retention window. No `Actor` can be
 * resolved for a deleted org — sign-in and the org switcher both hide it —
 * so the caller is identified by a bare `userId`, and the actor used for the
 * `org:restore` check is assembled from the caller's still-live membership
 * row once every other precondition has passed.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) {
    throw new NotFoundError("Organization", orgId);
  }

  if (org.archivedAt === null) {
    return org;
  }

  const cutoff =
    new Date(org.archivedAt).getTime() +
    DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
  if (Date.now() >= cutoff) {
    throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId, role: member.role };
  assertCan(actor, "org:restore", orgResource(orgId));

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

